def transform(grid):
    h,w=len(grid),len(grid[0]); result=[]
    for r in range(0,h,3):
        row=[]
        for c in range(0,w,3):
            counts=Counter(v for rr in grid[r:r+3] for v in rr[c:c+3] if v!=5)
            row.append(counts.most_common(1)[0][0] if counts else 5)
        result.append(row)
    return result
